window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e65474f518e673bf"]={"versions": [{"id": "FIG-e65474f518e673bf", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Metamodells im Kontext der Sender-Kommunikationsspezifikation (<code>SenderComSpec</code>) von Software-Komponenten-Ports (Classic Platform). Dargestellt ist die strukturelle Modellierung senderseitiger Kommunikationsattribute, ihrer Vererbungshierarchie von <code>PPortComSpec</code>, der Anbindung an Datenprototypen (<code>VariableDataPrototype</code>) sowie Mechanismen zur End-to-End-Absicherung (<code>usesEndToEndProtection</code>), Übertragungsbestätigung und Netzwerkdatenrepräsentation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>SenderComSpec</code>: Abstrakte Basisklasse, spezialisiert von <code>PPortComSpec</code> (über Komposition <code>+providedComSpec 0..*</code> an <code>AbstractProvidedPortPrototype</code> angebunden). Enthält die Attribute <code>handleOutOfRange: HandleOutOfRangeEnum</code> und <code>«atpVariation» usesEndToEndProtection: Boolean</code>.</li>\n<li>Subklassen von <code>SenderComSpec</code>:</li>\n<li><code>QueuedSenderComSpec</code>: Modellierung für gepufferte Senderkommunikation.</li>\n<li><code>NonqueuedSenderComSpec</code>: Modellierung für ungepufferte Senderkommunikation; besitzt eine Komposition <code>+initValue 1</code> zu <code>ValueSpecification</code> (mit Attribut <code>shortLabel: Identifier [0..1]</code>).</li>\n<li>Assoziationen und Kompositionen von <code>SenderComSpec</code>:</li>\n<li><code>+dataElement 1</code>: Gerichtete Assoziation auf <code>VariableDataPrototype</code> (Spezialisierung von <code>AutosarDataPrototype</code>).</li>\n<li><code>+transmissionAcknowledge 0..1</code>: Komposition zu <code>TransmissionAcknowledgementRequest</code> mit Attribut <code>timeout: TimeValue</code>.</li>\n<li><code>+networkRepresentation 0..1</code>: Komposition zum Variation Point <code>«atpVariation» SwDataDefProps</code>.</li>\n<li><code>+compositeNetworkRepresentation 0..*</code>: Komposition zu <code>CompositeNetworkRepresentation</code>.</li>\n<li><code>CompositeNetworkRepresentation</code>: Enthält eine Komposition <code>+networkRepresentation 1</code> zu <code>«atpVariation» SwDataDefProps</code> und referenziert über die Instanzreferenz <code>«instanceRef» +leafElement 1</code> ein <code>ApplicationCompositeElementDataPrototype</code> (Spezialisierung von <code>DataPrototype</code>).</li>\n<li><code>HandleOutOfRangeEnum</code>: Enumeration mit den Literalen <code>none</code>, <code>ignore</code>, <code>saturate</code>, <code>default</code>, <code>invalid</code>, <code>externalReplacement</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Struktur ohne explizite Ablauf- oder Sequenzpfade. Zur Laufzeit- und Konfigurationszeit bestimmt die Instanz von <code>SenderComSpec</code> über <code>usesEndToEndProtection</code>, ob Daten vor dem Senden durch die E2E-Library abgesichert werden. Bei aktivierter Übertragungsquittierung überwacht <code>TransmissionAcknowledgementRequest</code> den Sendevorgang mit einem Timeout (<code>timeout</code>). Wertebereichsüberschreitungen werden gemäß <code>handleOutOfRange</code> behandelt (z. B. Sättigung oder Invalidierung), und ungepufferte Signale werden bei Initialisierung mit dem über <code>initValue</code> festgelegten <code>ValueSpecification</code>-Wert vorbelegt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung für AUTOSAR-Autoren und Werkzeughersteller (Classic Platform BSW/RTE/E2E):</p>\n<ul class=\"fig-list\">\n<li>Jede <code>SenderComSpec</code> muss verbindlich genau ein <code>VariableDataPrototype</code> als <code>+dataElement</code> referenzieren (Kardinalität <code>1</code>).</li>\n<li><code>usesEndToEndProtection</code> ist als Variationspunkt (<code>«atpVariation»</code>) ausgelegt und steuert verbindlich das Enforcieren des E2E-Schutzes im RTE/COM-Stack.</li>\n<li>Für ungepufferte Ports (<code>NonqueuedSenderComSpec</code>) ist die Angabe eines Initialwerts (<code>initValue</code>) mit Kardinalität <code>1</code> obligatorisch.</li>\n<li>Das Vorhandensein von <code>TransmissionAcknowledgementRequest</code> ist optional (<code>0..1</code>).</li>\n<li>Bereichsüberschreitungen müssen zwingend auf eines der definierten Literale von <code>HandleOutOfRangeEnum</code> abgebildet werden.</li>\n</ul>"}, {"id": "FIG-d8c9bd940b5df82b", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Metamodells im Kontext der Sender-Kommunikationsspezifikation (<code>SenderComSpec</code>) von Software-Komponenten-Ports (Classic Platform). Dargestellt ist die strukturelle Modellierung senderseitiger Kommunikationsattribute, ihrer Vererbungshierarchie von <code>PPortComSpec</code>, der Anbindung an Datenprototypen (<code>VariableDataPrototype</code>) sowie Mechanismen zur End-to-End-Absicherung (<code>usesEndToEndProtection</code>), Übertragungsbestätigung und Netzwerkdatenrepräsentation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>SenderComSpec</code>: Abstrakte Basisklasse, spezialisiert von <code>PPortComSpec</code> (über Komposition <code>+providedComSpec 0..*</code> an <code>AbstractProvidedPortPrototype</code> angebunden). Enthält die Attribute <code>handleOutOfRange: HandleOutOfRangeEnum</code> und <code>«atpVariation» usesEndToEndProtection: Boolean</code>.</li>\n<li>Subklassen von <code>SenderComSpec</code>:</li>\n<li><code>QueuedSenderComSpec</code>: Modellierung für gepufferte Senderkommunikation.</li>\n<li><code>NonqueuedSenderComSpec</code>: Modellierung für ungepufferte Senderkommunikation; besitzt eine Komposition <code>+initValue 1</code> zu <code>ValueSpecification</code> (mit Attribut <code>shortLabel: Identifier [0..1]</code>).</li>\n<li>Assoziationen und Kompositionen von <code>SenderComSpec</code>:</li>\n<li><code>+dataElement 0..1</code>: Gerichtete Assoziation auf <code>AutosarDataPrototype</code> (Spezialisierung von <code>DataPrototype</code>; wird generalisierend über <code>VariableDataPrototype</code> erweitert).</li>\n<li><code>+transmissionAcknowledge 0..1</code>: Komposition zu <code>TransmissionAcknowledgementRequest</code> mit Attribut <code>timeout: TimeValue</code>.</li>\n<li><code>+networkRepresentation 0..1</code>: Komposition zum Variation Point <code>«atpVariation» SwDataDefProps</code>.</li>\n<li><code>+compositeNetworkRepresentation 0..*</code>: Komposition zu <code>CompositeNetworkRepresentation</code>.</li>\n<li><code>CompositeNetworkRepresentation</code>: Enthält eine Komposition <code>+networkRepresentation 1</code> zu <code>«atpVariation» SwDataDefProps</code> und referenziert über die Instanzreferenz <code>«instanceRef» +leafElement 1</code> ein <code>ApplicationCompositeElementDataPrototype</code> (Spezialisierung von <code>DataPrototype</code>).</li>\n<li><code>HandleOutOfRangeEnum</code>: Enumeration mit den Literalen <code>none</code>, <code>ignore</code>, <code>saturate</code>, <code>default</code>, <code>invalid</code>, <code>externalReplacement</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Struktur ohne explizite Ablauf- oder Sequenzpfade. Zur Laufzeit- und Konfigurationszeit bestimmt die Instanz von <code>SenderComSpec</code> über <code>usesEndToEndProtection</code>, ob Daten vor dem Senden durch die E2E-Library abgesichert werden. Bei aktivierter Übertragungsquittierung überwacht <code>TransmissionAcknowledgementRequest</code> den Sendevorgang mit einem Timeout (<code>timeout</code>). Wertebereichsüberschreitungen werden gemäß <code>handleOutOfRange</code> behandelt (z. B. Sättigung oder Invalidierung), und ungepufferte Signale werden bei Initialisierung mit dem über <code>initValue</code> festgelegten <code>ValueSpecification</code>-Wert vorbelegt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung für AUTOSAR-Autoren und Werkzeughersteller (Classic Platform BSW/RTE/E2E):</p>\n<ul class=\"fig-list\">\n<li>Eine <code>SenderComSpec</code> referenziert über die Assoziation <code>+dataElement</code> optional bis zu ein <code>AutosarDataPrototype</code> (Kardinalität <code>0..1</code>), welches durch <code>VariableDataPrototype</code> spezialisiert werden kann.</li>\n<li><code>usesEndToEndProtection</code> ist als Variationspunkt (<code>«atpVariation»</code>) ausgelegt und steuert verbindlich das Enforcieren des E2E-Schutzes im RTE/COM-Stack.</li>\n<li>Für ungepufferte Ports (<code>NonqueuedSenderComSpec</code>) ist die Angabe eines Initialwerts (<code>initValue</code>) mit Kardinalität <code>1</code> obligatorisch.</li>\n<li>Das Vorhandensein von <code>TransmissionAcknowledgementRequest</code> ist optional (<code>0..1</code>).</li>\n<li>Bereichsüberschreitungen müssen zwingend auf eines der definierten Literale von <code>HandleOutOfRangeEnum</code> abgebildet werden.</li>\n</ul>"}], "trans": [{"from": "FIG-e65474f518e673bf", "to": "FIG-d8c9bd940b5df82b", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Die Assoziation <code>SenderComSpec</code> zu <code>AutosarDataPrototype</code> (<code>+dataElement</code>) ändert ihre Ziel-Kardinalität von <code>1</code> auf <code>0..1</code>.</li>\n<li>Der Zieltyp der Assoziation <code>+dataElement</code> ist nun explizit die Basisklasse <code>AutosarDataPrototype</code> (mit Spezialisierung durch <code>VariableDataPrototype</code>), anstatt direkt der Subtyp <code>VariableDataPrototype</code>.</li>\n</ul>"}]};
